}
const amountOf = (money) => {
    const n = Number(money?.convertedAmount ?? money?.amount);
    return Number.isFinite(n) ? n : 0;
};
export const cartCurrency = (raw) => raw?.customerInfo?.currencyCode ?? raw?.businessInfo?.currencyCode ?? "";
